WITH exploded AS (SELECT id, host, log_ts, level, latency_ms, status_code, k, v FROM app_logs LATERAL VIEW EXPLODE(context) t AS k, v), metrics AS (SELECT *, LAST_VALUE(k) IGNORE NULLS OVER (PARTITION BY level ORDER BY latency_ms, id, k ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_k, NTILE(5) OVER (PARTITION BY host, k ORDER BY latency_ms DESC, id, k) AS latency_ms_bucket FROM exploded WHERE latency_ms BETWEEN 899 AND 1324), latest AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY level ORDER BY status_code DESC, id, k) AS row_num FROM metrics) t WHERE row_num = 1), base AS (SELECT id, host, log_ts, status_code, k, v, last_known_k, latency_ms_bucket, row_num, SUBSTRING(k, 1, 4) AS k_prefix FROM latest WHERE k IS NOT NULL AND status_code > 268), valid AS (SELECT *, COALESCE(k, 'unassigned') AS k_filled, COALESCE(k, 'OTHER') AS k_filled_2 FROM base WHERE k IS NOT NULL AND status_code >= 358), with_gaps AS (SELECT *, CASE WHEN log_ts - LAG(log_ts) OVER (PARTITION BY k ORDER BY log_ts, id, k) > INTERVAL '1' HOUR THEN 1 ELSE 0 END AS is_new_burst FROM valid), islands AS (SELECT id, log_ts, status_code, k, v, row_num, k_prefix, SUM(is_new_burst) OVER (PARTITION BY k ORDER BY log_ts, id, k ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM with_gaps) SELECT CASE WHEN session_id >= 8 THEN 'HIGH' ELSE 'LOW' END AS session_id_tier, session_id, SUM(status_code) FILTER (WHERE k = 'version') AS version_total_status_code, (UNIX_TIMESTAMP(MAX(log_ts)) - UNIX_TIMESTAMP(MIN(log_ts))) / 60 AS span_minutes, COUNT(DISTINCT k) AS distinct_ks, GROUPING(CASE WHEN session_id >= 8 THEN 'HIGH' ELSE 'LOW' END) AS gid FROM islands GROUP BY ROLLUP (CASE WHEN session_id >= 8 THEN 'HIGH' ELSE 'LOW' END, session_id)
